     1|/*
     2| * IVX Investor-First Home Feed — ivxholding.com
     3| *
     4| * Enforces the CANONICAL home layout from the single source of truth
     5| * (GET /api/ivx/video-platform/home-feed) — the exact same sequence the
     6| * Android and iOS apps render:
     7| *
     8| *   Featured Deal 1–3 → 1 Featured Project Video → Deal 4–6 → 1 video → repeat
     9| *
    10| * Behaviour:
    11| *   • Reorders the rendered deal cards in #properties-grid to the canonical order.
    12| *   • Inserts exactly ONE featured project video card after every 3 deals.
    13| *   • Every video card is attached to a real project (name, city, phase,
    14| *     investment, ROI, minimum, progress %, View Deal + Invest Now).
    15| *   • Performance: poster image loads first; the video source attaches only
    16| *     when the card scrolls into view; only the next upcoming video preloads.
    17| *   • Admin publish (deal/video meta) updates this page automatically on the
    18| *     next load — no separate configuration.
    19| */
    20|(function () {
    21|  'use strict';
    22|  if (window.__ivxHomeFeedLoaded) return;
    23|  window.__ivxHomeFeedLoaded = true;
    24|
    25|  var API_CANDIDATES = ['https://api.ivxholding.com', 'https://ivx-holdings-platform.onrender.com'];
    26|  var HLS_CDN = 'https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js';
    27|
    28|  var homeFeed = null;      /* canonical blocks from the backend */
    29|  var applying = false;     /* guard against observer feedback loops */
    30|
    31|  /* ---------- helpers ---------- */
    32|  function esc(s) {
    33|    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    34|      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    35|    });
    36|  }
    37|  function money(n) {
    38|    n = Number(n) || 0;
    39|    if (n >= 1000000) return '$' + (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 1) + 'M';
    40|    if (n >= 1000) return '$' + (n / 1000).toFixed(n % 1000 === 0 ? 0 : 1) + 'K';
    41|    return '$' + Math.round(n);
    42|  }
    43|  function parseMetric(v) {
    44|    if (v == null || v === '') return null;
    45|    var n = Number(v);
    46|    return isNaN(n) || n <= 0 ? null : n;
    47|  }
    48|  function formatRoi(n) {
    49|    if (n == null) return '';
    50|    if (n >= 100) return Math.round(n) + '%';
    51|    return n.toFixed(n % 1 === 0 ? 0 : 2) + '%';
    52|  }
    53|
    54|  function fetchHomeFeed(i) {
    55|    i = i || 0;
    56|    if (i >= API_CANDIDATES.length) return Promise.reject(new Error('all API hosts failed'));
    57|    return fetch(API_CANDIDATES[i] + '/api/ivx/video-platform/home-feed?limit=60')
    58|      .then(function (r) {
    59|        var ct = (r.headers.get('content-type') || '').toLowerCase();
    60|        if (!r.ok || ct.indexOf('json') === -1) throw new Error('bad response');
    61|        return r.json();
    62|      })
    63|      .catch(function () { return fetchHomeFeed(i + 1); });
    64|  }
    65|
    66|  /* ---------- lazy HLS ---------- */
    67|  var hlsLoading = null;
    68|  function loadHlsJs() {
    69|    if (window.Hls) return Promise.resolve();
    70|    if (hlsLoading) return hlsLoading;
    71|    hlsLoading = new Promise(function (resolve) {
    72|      var s = document.createElement('script');
    73|      s.src = HLS_CDN; s.async = true;
    74|      s.onload = function () { resolve(); };
    75|      s.onerror = function () { resolve(); };
    76|      document.head.appendChild(s);
    77|    });
    78|    return hlsLoading;
    79|  }
    80|  function attachSource(video, hlsUrl, fallbackUrl) {
    81|    if (video.__ivxAttached) return;
    82|    video.__ivxAttached = true;
    83|    if (!hlsUrl) { if (fallbackUrl) video.src = fallbackUrl; return; }
    84|    if (video.canPlayType('application/vnd.apple.mpegurl')) { video.src = hlsUrl; return; }
    85|    loadHlsJs().then(function () {
    86|      if (window.Hls && window.Hls.isSupported()) {
    87|        var h = new window.Hls({ capLevelToPlayerSize: true, maxBufferLength: 15 });
    88|        h.on(window.Hls.Events.ERROR, function (_e, data) {
    89|          if (data && data.fatal) { try { h.destroy(); } catch (e) {} if (fallbackUrl) video.src = fallbackUrl; }
    90|        });
    91|        h.loadSource(hlsUrl);
    92|        h.attachMedia(video);
    93|        video.__ivxHls = h;
    94|      } else if (fallbackUrl) {
    95|        video.src = fallbackUrl;
    96|      }
    97|    });
    98|  }
    99|
   100|  /* ---------- styles ---------- */
   101|  var css = ''
   102|    + '.ivx-hf-video{grid-column:1/-1;position:relative;background:#000;border-radius:18px;overflow:hidden;'
   103|    + 'width:100%;max-width:480px;margin:0 auto;aspect-ratio:9/16;min-height:560px;max-height:88vh;display:flex;flex-direction:column}'
   104|    + '.ivx-hf-media{position:absolute;inset:0;background:#000;overflow:hidden}'
   105|    + '.ivx-hf-media img,.ivx-hf-media video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}'
   106|    + '.ivx-hf-gradient{position:absolute;left:0;right:0;bottom:0;height:320px;'
   107|    + 'background:linear-gradient(to top,rgba(0,0,0,.82),rgba(0,0,0,.55),transparent);z-index:2;pointer-events:none}'
   108|    + '.ivx-hf-tag{position:absolute;top:12px;left:12px;z-index:5;background:#FFD700;color:#000;border-radius:5px;'
   109|    + 'padding:3px 8px;font:800 10px/1 -apple-system,Segoe UI,sans-serif;text-transform:uppercase;letter-spacing:.4px}'
   110|    + '.ivx-hf-mute{position:absolute;top:12px;right:12px;z-index:5;background:rgba(0,0,0,.35);color:#fff;border:none;'
   111|    + 'border-radius:50%;width:38px;height:38px;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center}'
   112|    + '.ivx-hf-rail{position:absolute;right:10px;bottom:96px;z-index:5;display:flex;flex-direction:column;gap:16px;align-items:center}'
   113|    + '.ivx-hf-act{background:none;border:none;color:#fff;cursor:pointer;text-align:center;padding:0;'
   114|    + 'filter:drop-shadow(0 1px 3px rgba(0,0,0,.6))}'
   115|    + '.ivx-hf-act .ic{width:44px;height:44px;border-radius:50%;background:rgba(0,0,0,.25);display:flex;align-items:center;justify-content:center}'
   116|    + '.ivx-hf-act .i{font-size:24px;line-height:1;display:block}'
   117|    + '.ivx-hf-act .c{font:700 11px/1 -apple-system,sans-serif;margin-top:3px;display:block}'
   118|    + '.ivx-hf-act.on .ic{color:#e0245e}'
   119|    + '.ivx-hf-act.saved .ic{color:#E6C200}'
   120|    + '.ivx-hf-info{position:absolute;left:14px;right:84px;bottom:26px;z-index:5;color:#fff;pointer-events:none}'
   121|    + '.ivx-hf-badges{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}'
   122|    + '.ivx-hf-badge{display:inline-block;background:#FFD700;color:#000;border-radius:5px;padding:3px 8px;'
   123|    + 'font:800 10px/1 -apple-system,sans-serif;text-transform:uppercase;letter-spacing:.4px}'
   124|    + '.ivx-hf-badge.active{background:rgba(0,0,0,.55);border:1px solid #FFD700;color:#FFD700}'
   125|    + '.ivx-hf-name{font:800 22px/1.2 -apple-system,Segoe UI,sans-serif;text-shadow:0 1px 4px rgba(0,0,0,.7);margin-bottom:2px}'
   126|    + '.ivx-hf-loc{font:600 13px/1.3 -apple-system,sans-serif;color:rgba(255,255,255,.85);'
   127|    + 'text-shadow:0 1px 4px rgba(0,0,0,.7);margin-top:2px}'
   128|    + '.ivx-hf-subtitle{font:600 15px/1.3 -apple-system,sans-serif;color:rgba(255,255,255,.9);'
   129|    + 'text-shadow:0 1px 4px rgba(0,0,0,.7);margin-top:2px}'
   130|    + '.ivx-hf-stats{display:flex;gap:22px;margin-top:8px;flex-wrap:wrap}'
   131|    + '.ivx-hf-stat{text-align:center}'
   132|    + '.ivx-hf-stat .v{font:800 20px/1 -apple-system,sans-serif;color:#FFD700}'
   133|    + '.ivx-hf-stat .l{color:rgba(255,255,255,.75);font:600 10px/1 -apple-system,sans-serif;text-transform:uppercase;margin-top:4px}'
   134|    + '.ivx-hf-options{display:flex;gap:14px;margin-top:10px}'
   135|    + '.ivx-hf-opt{display:flex;flex-direction:column;align-items:center;gap:4px}'
   136|    + '.ivx-hf-opt .circ{width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;'
   137|    + 'background:rgba(0,0,0,.35);border:1.5px solid rgba(255,255,255,.25)}'
   138|    + '.ivx-hf-opt .circ.yellow{border-color:#FFD700;color:#FFD700}'
   139|    + '.ivx-hf-opt .circ.blue{border-color:#4A90D9;color:#4A90D9}'
   140|    + '.ivx-hf-opt .circ.green{border-color:#3CCF4E;color:#3CCF4E}'
   141|    + '.ivx-hf-opt .lab{font:600 10px/1 -apple-system,sans-serif;color:#fff}'
   142|    + '.ivx-hf-btns{display:flex;gap:10px;margin-top:14px;pointer-events:auto}'
   143|    + '.ivx-hf-btns a{flex:1;text-align:center;border-radius:999px;padding:13px 0;font:800 15px/1 -apple-system,Segoe UI,sans-serif;'
   144|    + 'text-decoration:none;cursor:pointer}'
   145|    + '.ivx-hf-view{background:rgba(0,0,0,.45);color:#FFD700;border:2px solid #FFD700}'
   146|    + '.ivx-hf-invest{background:#FFD700;color:#000}';
   147|  var styleEl = document.createElement('style');
   148|  styleEl.textContent = css;
   149|  document.head.appendChild(styleEl);
   150|
   151|  /* SVG icons for the action rail and option circles */
   152|  var ICONS = {
   153|    heart: '&#9825;',
   154|    heartFilled: '&#10084;',
   155|    comment: '&#128172;',
   156|    bookmark: '&#128279;',
   157|    bookmarkFilled: '&#128278;',
   158|    share: '&#10148;',
   159|    mute: '&#128263;',
   160|    unmute: '&#128266;',
   161|    hex: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path></svg>',
   162|    users: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>',
   163|    home: '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path><polyline points="9 22 9 12 15 12 15 22"></polyline></svg>'
   164|  };
   165|
   166|  /* ---------- featured project video card ---------- */
   167|  function buildVideoCard(v) {
   168|    var deal = v.deal || {};
   169|    var card = document.createElement('div');
   170|    card.className = 'ivx-hf-video';
   171|    card.setAttribute('data-ivx-home-feed-video', v.id);
   172|
   173|    var poster = v.poster_url || v.thumbnail_url || v.preview_blur_url || '';
   174|    var dealUrl = deal.url || 'https://ivxholding.com/?deal=' + encodeURIComponent(deal.id || v.id) + '#deals';
   175|    var title = deal.name || v.title || 'IVX Project';
   176|    var location = deal.city || '';
   177|    var roi = parseMetric(deal.expected_roi);
   178|    var minInvest = parseMetric(deal.min_investment);
   179|    var price = parseMetric(deal.price);
   180|    var minOwnership = (minInvest && price && price > 0) ? ((minInvest / price) * 100).toFixed(4) + '%' : null;
   181|    var dealType = (deal.deal_type || '').toLowerCase();
   182|    var isActive = (deal.status || v.status || 'published') === 'published';
   183|
   184|    var tokenized = { icon: ICONS.hex, label: 'Tokenized', cls: 'yellow' };
   185|    var jvDeals = { icon: ICONS.users, label: 'JV Deal', cls: 'blue' };
   186|    var buyers = { icon: ICONS.home, label: 'Buyer', cls: 'green' };
   187|    var options;
   188|    switch (dealType) {
   189|      case 'jv': case 'equity_split': case 'hybrid': options = [tokenized, jvDeals, buyers]; break;
   190|      case 'development': case 'new_construction': case 'rehab_construction': options = [jvDeals, tokenized, buyers]; break;
   191|      case 'profit_sharing': options = [tokenized, buyers, jvDeals]; break;
   192|      default: options = [tokenized, jvDeals, buyers];
   193|    }
   194|
   195|    var statsHtml = '';
   196|    if (price) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + money(price) + '</div><div class="l">Investment</div></div>';
   197|    if (roi) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + formatRoi(roi) + '</div><div class="l">ROI</div></div>';
   198|    if (minInvest) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + money(minInvest) + '</div><div class="l">Minimum</div></div>';
   199|    if (!statsHtml && minOwnership) statsHtml += '<div class="ivx-hf-stat"><div class="v">' + esc(minOwnership) + '</div><div class="l">Min Ownership</div></div>';
   200|
   201|    var optionsHtml = options.map(function (opt) {
   202|      return '<div class="ivx-hf-opt"><div class="circ ' + opt.cls + '">' + opt.icon + '</div><div class="lab">' + esc(opt.label) + '</div></div>';
   203|    }).join('');
   204|
   205|    var hasDeal = !!(deal.id || v.id);
   206|    var ctaHtml = '';
   207|    if (hasDeal) {
   208|      ctaHtml = '<div class="ivx-hf-btns">'
   209|        + '<a class="ivx-hf-view" href="' + esc(dealUrl) + '">View Deal</a>'
   210|        + '<a class="ivx-hf-invest" href="' + esc(dealUrl) + '">Invest Now</a>'
   211|        + '</div>';
   212|    }
   213|
   214|    var badgesHtml = '';
   215|    if (hasDeal) badgesHtml += '<span class="ivx-hf-badge">Investment</span>';
   216|    if (isActive) badgesHtml += '<span class="ivx-hf-badge active">Active</span>';
   217|
   218|    card.innerHTML = ''
   219|      + '<div class="ivx-hf-media">'
   220|      + '  <span class="ivx-hf-tag">Featured Project Video</span>'
   221|      + (poster ? '<img src="' + esc(poster) + '" alt="' + esc(title) + '" loading="lazy"/>' : '')
   222|      + '  <video playsinline muted loop preload="none"' + (poster ? ' poster="' + esc(poster) + '"' : '') + ' style="opacity:0"></video>'
   223|      + '  <button class="ivx-hf-mute" aria-label="Unmute">' + ICONS.mute + '</button>'
   224|      + '  <div class="ivx-hf-gradient"></div>'
   225|      + '</div>'
   226|      + '<div class="ivx-hf-rail">'
   227|      + '  <button class="ivx-hf-act like' + (v.viewer_liked ? ' on' : '') + '"><span class="ic">' + (v.viewer_liked ? ICONS.heartFilled : ICONS.heart) + '</span><span class="c">' + fmt(v.like_count) + '</span></button>'
   228|      + '  <button class="ivx-hf-act cmt"><span class="ic">' + ICONS.comment + '</span><span class="c">' + fmt(v.comment_count) + '</span></button>'
   229|      + '  <button class="ivx-hf-act sav' + (v.viewer_saved ? ' saved' : '') + '"><span class="ic">' + (v.viewer_saved ? ICONS.bookmarkFilled : ICONS.bookmark) + '</span><span class="c">' + fmt(v.save_count) + '</span></button>'
   230|      + '  <button class="ivx-hf-act shr"><span class="ic">' + ICONS.share + '</span><span class="c">' + fmt(v.share_count) + '</span></button>'
   231|      + '</div>'
   232|      + '<div class="ivx-hf-info">'
   233|      + (badgesHtml ? '<div class="ivx-hf-badges">' + badgesHtml + '</div>' : '')
   234|      + '  <div class="ivx-hf-name">' + esc(title) + '</div>'
   235|      + (location ? '<div class="ivx-hf-loc">&#128205; ' + esc(location) + '</div>' : '')
   236|      + (statsHtml ? '<div class="ivx-hf-stats">' + statsHtml + '</div>' : '')
   237|      + (optionsHtml ? '<div class="ivx-hf-options">' + optionsHtml + '</div>' : '')
   238|      + ctaHtml
   239|      + '</div>';
   240|
   241|    var vid = card.querySelector('video');
   242|    var img = card.querySelector('.ivx-hf-media img');
   243|    var muteBtn = card.querySelector('.ivx-hf-mute');
   244|    var likeBtn = card.querySelector('.ivx-hf-act.like');
   245|    var saveBtn = card.querySelector('.ivx-hf-act.sav');
   246|    var shareBtn = card.querySelector('.ivx-hf-act.shr');
   247|
   248|    muteBtn.addEventListener('click', function () {
   249|      vid.muted = !vid.muted;
   250|      muteBtn.innerHTML = vid.muted ? ICONS.mute : ICONS.unmute;
   251|    });
   252|    likeBtn.addEventListener('click', function (e) {
   253|      e.stopPropagation();
   254|      toggleLike(v, likeBtn);
   255|    });
   256|    saveBtn.addEventListener('click', function (e) {
   257|      e.stopPropagation();
   258|      toggleSave(v, saveBtn);
   259|    });
   260|    shareBtn.addEventListener('click', function (e) {
   261|      e.stopPropagation();
   262|      shareVideo(v, shareBtn);
   263|    });
   264|
   265|    /* Lazy playback: attach the source ONLY when visible; images load first. */
   266|    card.__ivxActivate = function () {
   267|      attachSource(vid, v.hls_url, v.video_url);
   268|      vid.play().then(function () {
   269|        vid.style.opacity = '1';
   270|        if (img) img.style.opacity = '0';
   271|      }).catch(function () {});
   272|    };
   273|    card.__ivxDeactivate = function () { try { vid.pause(); } catch (e) {} };
   274|    card.__ivxPreload = function () {
   275|      /* preload the NEXT featured video only — metadata, no full download */
   276|      if (!vid.__ivxAttached) { vid.preload = 'metadata'; attachSource(vid, v.hls_url, v.video_url); }
   277|    };
   278|    return card;
   279|  }
   280|
   281|  function fmt(n) {
   282|    n = Number(n) || 0;
   283|    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
   284|    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
   285|    return String(n);
   286|  }
   287|
   288|  function toggleLike(v, btn) {
   289|    fetch('https://api.ivxholding.com/api/projects/' + encodeURIComponent(v.id) + '/like', {
   290|      method: 'POST', headers: { 'Content-Type': 'application/json' },
   291|      body: JSON.stringify({ guest_id: localStorage.getItem('ivx_viewer_id') || 'guest-anon' })
   292|    }).then(function (r) { return r.json(); }).then(function (d) {
   293|      btn.classList.toggle('on', !!d.liked);
   294|      btn.querySelector('.ic').innerHTML = d.liked ? ICONS.heartFilled : ICONS.heart;
   295|      btn.querySelector('.c').textContent = fmt(d.like_count);
   296|    }).catch(function () {});
   297|  }
   298|
   299|  function toggleSave(v, btn) {
   300|    fetch('https://api.ivxholding.com/api/projects/' + encodeURIComponent(v.id) + '/save', {
   301|      method: 'POST', headers: { 'Content-Type': 'application/json' },
   302|      body: JSON.stringify({ guest_id: localStorage.getItem('ivx_viewer_id') || 'guest-anon' })
   303|    }).then(function (r) { return r.json(); }).then(function (d) {
   304|      btn.classList.toggle('saved', !!d.saved);
   305|      btn.querySelector('.ic').innerHTML = d.saved ? ICONS.bookmarkFilled : ICONS.bookmark;
   306|      btn.querySelector('.c').textContent = fmt(d.save_count);
   307|    }).catch(function () {});
   308|  }
   309|
   310|  function shareVideo(v) {
   311|    var url = 'https://ivxholding.com/?video=' + encodeURIComponent(v.id);
   312|    if (navigator.share) {
   313|      navigator.share({ title: v.title || 'IVX Property Video', url: url }).catch(function () {});
   314|    } else if (navigator.clipboard) {
   315|      navigator.clipboard.writeText(url).catch(function () {});
   316|    }
   317|    fetch('https://api.ivxholding.com/api/projects/' + encodeURIComponent(v.id) + '/share', {
   318|      method: 'POST', headers: { 'Content-Type': 'application/json' },
   319|      body: JSON.stringify({ guest_id: localStorage.getItem('ivx_viewer_id') || 'guest-anon', share_type: 'social', share_url: url })
   320|    }).catch(function () {});
   321|  }
   322|
   323|  var videoIO = null;
   324|  function observeVideoCards(grid) {
   325|    if (!videoIO) {
   326|      videoIO = new IntersectionObserver(function (entries) {
   327|        entries.forEach(function (entry) {
   328|          var card = entry.target;
   329|          if (entry.isIntersecting && entry.intersectionRatio >= 0.35) {
   330|            if (card.__ivxActivate) card.__ivxActivate();
   331|            /* preload only the next upcoming video card */
   332|            var all = Array.prototype.slice.call(document.querySelectorAll('[data-ivx-home-feed-video]'));
   333|            var idx = all.indexOf(card);
   334|            if (idx >= 0 && all[idx + 1] && all[idx + 1].__ivxPreload) all[idx + 1].__ivxPreload();
   335|          } else if (!entry.isIntersecting && card.__ivxDeactivate) {
   336|            card.__ivxDeactivate();
   337|          }
   338|        });
   339|      }, { threshold: [0, 0.35] });
   340|    }
   341|    grid.querySelectorAll('[data-ivx-home-feed-video]').forEach(function (card) {
   342|      if (!card.__ivxObserved) { card.__ivxObserved = true; videoIO.observe(card); }
   343|    });
   344|  }
