  3328|  function vxAgo(iso) {
  3329|    if (!iso) return '';
  3330|    var t = new Date(iso).getTime();
  3331|    if (!isFinite(t)) return '';
  3332|    var s = Math.max(0, Math.floor((Date.now() - t) / 1000));
  3333|    if (s < 60) return 'Just now';
  3334|    var m = Math.floor(s / 60);
  3335|    if (m < 60) return m + (m === 1 ? ' minute ago' : ' minutes ago');
  3336|    var h = Math.floor(m / 60);
  3337|    if (h < 24) return h + (h === 1 ? ' hour ago' : ' hours ago');
  3338|    var d = Math.floor(h / 24);
  3339|    if (d < 7) return d + (d === 1 ? ' day ago' : ' days ago');
  3340|    var w = Math.floor(d / 7);
  3341|    if (w < 5) return w + (w === 1 ? ' week ago' : ' weeks ago');
  3342|    return new Date(iso).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' });
  3343|  }
